import DepartureStatistics from '../components/statistics/DepartureStatistics';
import { Card } from '@/types/statistics';
import DepartureList from '../components/departureList/DepartureList';
import { useEffect, useMemo, useState } from 'react';
import { format } from 'date-fns';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { Attendances } from '../types/attendances.types';
import Shifts from '../components/shifts/Shifts';

export default function DeparturePage() {
    const [todayRows, setTodayRows] = useState<Attendances[]>([]);
    const [selectedDate, setSelectedDate] = useState<Date>(new Date());

    useEffect(() => {
        const fetchToday = async () => {
            try {
                const res = await apiGet({
                    endpoint: endpoints.employee.attendance,
                    queryParams: {
                        page: 1,
                        pageSize: 5000,
                        // Use local calendar date — toISOString() is UTC and shifts the day in +TZ regions
                        date: format(selectedDate, 'yyyy-MM-dd'),
                    },
                });
                setTodayRows(res.data.data.data ?? []);
            } catch {
                setTodayRows([]);
            }
        };

        fetchToday();
    }, [selectedDate]);

    const cards: Card[] = useMemo(() => {
        const total = todayRows.length;
        const present = todayRows.filter((r) => r.status === 'present' || r.status === 'late').length;
        const absent = todayRows.filter((r) => r.status === 'absent').length;
        const leaves = todayRows.filter((r) => r.status === 'leave' || r.status === 'vacation' || r.status === 'holiday').length;
        const attendanceRate = total > 0 ? Math.round((present / total) * 100) : 0;

        return [
            { text: 'نسبة الحضور', num: `% ${attendanceRate}` },
            { text: 'إجمالي أيام الغياب', num: absent },
            { text: 'إجمالي الإجازات', num: leaves },
            { text: 'إجمالي المدفوع', num: '-' },
        ];
    }, [todayRows]);

    return (
        <div className="w-full mt-6 mb-20">
            <DepartureStatistics cards={cards} />
            <Shifts selectedDate={selectedDate} onSelectDate={setSelectedDate} />
            <DepartureList date={format(selectedDate, 'yyyy-MM-dd')} />
        </div>
    );
}
