import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { cn } from '@/lib/utils';
import { addDays, format, isAfter, startOfDay, startOfWeek } from 'date-fns';
import { useMemo } from 'react';

interface Props {
    selectedDate: Date;
    onSelectDate: (date: Date) => void;
}

const AR_DAYS = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];

export default function Shifts({ selectedDate, onSelectDate }: Props) {
    const weekStart = useMemo(() => startOfWeek(selectedDate, { weekStartsOn: 0 }), [selectedDate]);
    const days = useMemo(() => Array.from({ length: 7 }, (_, i) => addDays(weekStart, i)), [weekStart]);
    const todayStart = startOfDay(new Date());

    return (
        <div className="mt-6 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <div className="flex items-center justify-between p-4">
                <UnderlineHeading text="ورديات العمل" />
                <div className="text-sm text-white-blue-800">{format(selectedDate, 'yyyy-MM-dd')}</div>
            </div>

            <div className="grid grid-cols-7 gap-2 p-4 pt-0">
                {days.map((d) => {
                    const isSelected = format(d, 'yyyy-MM-dd') === format(selectedDate, 'yyyy-MM-dd');
                    const isFutureDay = isAfter(startOfDay(d), todayStart);
                    return (
                        <button
                            key={format(d, 'yyyy-MM-dd')}
                            type="button"
                            disabled={isFutureDay}
                            aria-disabled={isFutureDay}
                            onClick={() => {
                                if (!isFutureDay) onSelectDate(d);
                            }}
                            className={cn(
                                'rounded-lg border px-2 py-3 text-center transition-colors',
                                isFutureDay &&
                                    'cursor-not-allowed opacity-40 grayscale hover:bg-white hover:border-white-blue-200',
                                !isFutureDay && isSelected
                                    ? 'border-primery-blue-700 bg-primery-blue-50 text-primery-blue-900'
                                    : !isFutureDay &&
                                          'border-white-blue-200 bg-white hover:bg-white-blue-50',
                            )}
                        >
                            <div className="text-xs text-[#71717A] font-medium">{AR_DAYS[d.getDay()]}</div>
                            <div className="text-lg font-bold text-primery-blue-800">{format(d, 'd')}</div>
                            <div className="text-xs text-[#71717A]">{format(d, 'MMM')}</div>
                        </button>
                    );
                })}
            </div>
        </div>
    );
}
